// Deleting a creation never deletes the hand-in it points at (DBU-09): only this row goes.
// A file the creation held on its own stays in storage, like any other file nothing points at.
(async () => {
  try {
    const me = String(Inputs.userId || '');
    const id = String(Inputs.id || '');
    if (!me) throw new Error('no session user');
    const rows = id ? await Noodl.Records.query('Creation', { objectId: { equalTo: id } }, { limit: 2, plain: true }) : [];
    if (!rows[0] || rows[0].learner !== me) { Outputs.why = 'This is not one of your creations. Reload the page.'; Outputs.refuse(); return; }
    await Noodl.Records.delete(id, { className: 'Creation' });
    await Noodl.Records.create('Doorbell', { learner: me, topic: 'creation' },
      { acl: { [me]: { read: true }, 'role:staff': { read: true } } });
    Outputs.done();
  } catch (e) {
    console.error('[dbu:deleteCreation]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
